function l(t){return Math.floor((t-1)/4)+2}function g(t){return Math.floor((t-10)/2)}function h(t,e,o){return 10+t+(o?e:0)}function f(t,e,o,s,c,u=0){let a=t+e,i=o+s.reduce((n,r)=>n+r.level,0);if(c==="average"){if(o>1){let n=Math.floor(t/2)+1;a+=(o-1)*(n+e)}s.forEach(n=>{let r=Math.floor(n.hitDie/2)+1;a+=n.level*(r+e)})}else a=t+e+u+(i-1)*e;return a}export{l as a,g as b,h as c,f as d};
